var outputMsgs = [];
var payload = String(msg.payload || '');
var lines = payload.split('\n');
for (var i = 0; i < lines.length; i++) {
    var line = lines[i].trim();
    if (line.length > 0) {
        outputMsgs.push({payload: line});
    }
}
return [outputMsgs];

var data = msg.payload;
if (!data || typeof data !== 'object') {
    return null;
}

var ioaMap = env.get('IOA_MAP_JSON') || {};
if (typeof ioaMap === 'string') {
    try {
        ioaMap = JSON.parse(ioaMap);
    } catch (err) {
        node.error('[iec104-server-core] ConfigError: invalid IOA_MAP_JSON', msg);
        return null;
    }
}

var rawMsg = {payload: data};
var statusMsg = null;
var commandMsg = null;
var auditMsg = null;

if (data.type === 'connection' || data.event === 'connected' || data.event === 'disconnected') {
    var connected = data.event === 'connected' || data.connected === true;
    statusMsg = {
        payload: {
            iec104_connected: connected,
            ts: Date.now()
        }
    };
    node.status({
        fill: connected ? 'green' : 'red',
        shape: 'dot',
        text: connected ? 'connected' : 'disconnected'
    });
}

var typeNum = parseInt(data.type, 10);
var isCommand = typeNum === 45 || typeNum === 50 || typeNum === 100 || data.direction === 'command';
if (isCommand) {
    var ioa = String(parseInt(data.address, 10));
    var mapping = ioaMap[ioa];

    if ((typeNum === 45 || typeNum === 50) && mapping) {
        var eventId = Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
        var now = Date.now();
        var action = mapping.action || ('set_' + mapping.key);
        var value = data.value;

        if (typeNum === 50) {
            value = parseFloat(value) || 0;
        }

        commandMsg = {
            payload: {
                device_id: data.device_id || env.get('DEFAULT_DEVICE_ID') || 'device-01',
                zone_id: data.zone_id || env.get('DEFAULT_ZONE_ID') || 'zone-01',
                action: action,
                value: value,
                unit: mapping.unit || '',
                source: 'iec104',
                timestamp: now,
                event_id: eventId,
                ioa: parseInt(ioa, 10),
                iec104_type: data.type
            }
        };

        auditMsg = {
            payload: {
                event_id: eventId,
                source: 'iec104',
                device_id: commandMsg.payload.device_id,
                zone_id: commandMsg.payload.zone_id,
                action: action,
                value: value,
                lifecycle_stage: 'command_received',
                result: {status: 'forwarded_to_writeback'},
                timestamp: now
            }
        };
    }
}

return [rawMsg, statusMsg, commandMsg, auditMsg];

msg.payload = {
    error_type: 'Iec104ServerStderr',
    source: 'json-iec104-server',
    message: String(msg.payload || '').substring(0, 500),
    ts: Date.now()
};
return msg;

msg.payload = {
    error_type: 'Iec104ServerExit',
    source: 'json-iec104-server',
    message: String(msg.payload || '').substring(0, 500),
    ts: Date.now()
};
return msg;
